 ].join('\n');return cp.spawnSync('/bin/bash',['-c',script],{encoding:'utf8',timeout:5000,env:{...env,FIXTURE_REPO:repo,FIXTURE_STATE:state,FIXTURE_DSN:db,MULTICA_FLEET_INPUT:input,MULTICA_FLEET_OPERATOR:op}});};
