test('TestAnthropicPathPrefixPreserved',()=>{
 for(const url of ['https://ark.cn-beijing.volces.com/api/plan','https://provider.invalid','https://provider.invalid/v1/messages-test_~;=+$&(),!','https://provider.invalid/percent%25']){
  const f=fixture(),input=JSON.parse(fs.readFileSync(f.input));input.aurora.anthropic_base_url=url;f.change('aurora',input.aurora);f.prepare();
  check(JSON.parse(fs.readFileSync(f.input)).aurora.anthropic_base_url===url,'descriptor URL changed');
  check(JSON.parse(fs.readFileSync(path.join(f.state,'fleet','config.json'))).aurora.anthropic_base_url===url,'config lost URL prefix');
 }
});
