  const f=fixture(),input=JSON.parse(fs.readFileSync(f.input));input.aurora.anthropic_base_url=url;f.change('aurora',input.aurora);
  const r=f.invoke('prepare');check(r.status!==0&&r.stdout.includes('denied'),'invalid URL accepted: '+JSON.stringify(url));check(fs.readFileSync(f.log,'utf8')==='','external commands reached on invalid URL');
 }
});
