// Original proof denial must preserve the durable fence and every recovery input.
function proofSnapshot(f){const files={};const visit=p=>{const s=fs.lstatSync(p);if(s.isDirectory()){files[p]={mode:s.mode&511};for(const n of fs.readdirSync(p).sort())visit(path.join(p,n));}else files[p]={mode:s.mode&511,bytes:fs.readFileSync(p).toString('base64')};};for(const p of [f.state,f.input,f.profiles,f.profile,f.key,f.log+'.operator-state',f.log+'.docker'])visit(p);return JSON.stringify(files);}
function originalProofBranches(stopped){const failures=[];for(const kind of ['missing','null','corrupt','key','epoch','action','version','namespace','fleet-id','missing-completions','null-completions']){const f=fixture();f.prepare();if(stopped)check(f.invoke('up').status===0&&f.invoke('down').status===0,'Stop proof baseline failed');else check(f.invoke('destroy').status===0,'Delete proof baseline failed');fs.writeFileSync(path.join(f.state,'manifest.env'),'NAME=fixture\n');const sp=f.log+'.operator-state',s=JSON.parse(fs.readFileSync(sp));if(kind==='missing')delete s.manifest;else if(kind==='null')s.manifest=null;else if(kind==='corrupt')s.manifest='not a manifest';else if(kind==='missing-completions')delete s.manifest.completions;else if(kind==='null-completions')s.manifest.completions=null;else s.manifest[{'epoch':'generation','fleet-id':'fleet_id'}[kind]||kind]=kind==='epoch'?s.generation+1:kind==='version'?2:kind==='action'?(stopped?'delete':'stop'):'foreign';fs.writeFileSync(sp,JSON.stringify(s));const before=fs.readFileSync(f.log,'utf8'),inputs=proofSnapshot(f),r=f.dev('destroy'),after=fs.readFileSync(f.log,'utf8').slice(before.length);try{check(r.status!==0,kind+' original '+(stopped?'Stop':'Delete')+' proof accepted');check(!/start api|stop api|stop (fleet|web|desktop)|container start|compose --|network rm|UNAPPROVED|operator resume/.test(after),kind+' proof denial mutated API/resources/DB');check(proofSnapshot(f)===inputs,kind+' proof denial changed epoch/key/manifest/private inputs/registry');}catch(e){failures.push(e.message);}}check(failures.length===0,failures.join('; '));}
test('TestStoppedDestroyRestartsOwnedControlWithoutResume',()=>{originalProofBranches(true);const f=fixture();f.prepare();check(f.invoke('up').status===0&&f.invoke('down').status===0,'cycle baseline failed');
 const sp=f.log+'.operator-state',s=JSON.parse(fs.readFileSync(sp));check(s.action==='stop'&&Array.isArray(s.manifest.completions)&&s.manifest.completions.length===0,'valid original empty Stop proof missing');s.manifest=Object.fromEntries(Object.entries(s.manifest).reverse());fs.writeFileSync(sp,JSON.stringify(s));const original=fs.readFileSync(sp,'utf8');check(f.invoke('quiesce').status===0&&fs.readFileSync(sp,'utf8')===original,'Stop replay reconstructed original proof');
 const before=fs.readFileSync(f.log,'utf8'),r=f.dev('destroy'),after=fs.readFileSync(f.log,'utf8').slice(before.length);check(after.includes('operator destroy'),'destroy not reached');const next=JSON.parse(fs.readFileSync(sp));check(next.generation===s.generation+1&&next.key===s.key&&next.action==='delete'&&next.manifest.action==='delete'&&next.manifest.completions.length===0,'valid original Stop did not transition to completed Delete');check(after.indexOf('start api')<after.indexOf('container start control-id')&&after.indexOf('container start control-id')<after.indexOf('operator destroy'),'restart order wrong');check(!after.includes('operator resume'),'destroy reopened admission');check(!after.includes('UNAPPROVED'),'unapproved command attempted');});
