test('TestCompletedCleanupRetryChecksOriginalCycleAndCurrentAbsence',()=>{
 originalProofBranches(false);
const f=fixture();f.prepare();check(f.invoke('destroy').status===0,'first owned cleanup denied');const sp=f.log+'.operator-state',s=JSON.parse(fs.readFileSync(sp));s.manifest=Object.fromEntries(Object.entries(s.manifest).reverse());fs.writeFileSync(sp,JSON.stringify(s));
 const original=fs.readFileSync(sp,'utf8'),count=fs.readFileSync(f.log,'utf8').split('operator destroy').length;check(f.invoke('destroy').status===0,'completed cleanup retry denied');check(fs.readFileSync(f.log,'utf8').split('operator destroy').length===count+1,'original SQL cycle not rechecked');check(fs.readFileSync(sp,'utf8')===original,'same-action replay reconstructed original proof');fs.writeFileSync(f.log+'.orphan','');check(f.invoke('destroy').status!==0,'orphan accepted after completed cleanup');
 for(const kind of ['key','epoch','original-proof','replacement']){const f=fixture();f.prepare();check(f.invoke('destroy').status===0,'cleanup baseline denied');const ip=path.join(f.state,'fleet','identity.json');if(kind==='key'){const id=JSON.parse(fs.readFileSync(ip));id.operation_key='99999999-9999-4999-8999-999999999999';id.cleanup_intent_key=id.operation_key;id.cleanup_operation_key=id.operation_key;fs.writeFileSync(ip,JSON.stringify(id));}else if(kind==='epoch'){const op=JSON.parse(fs.readFileSync(f.log+'.operator-state'));op.generation++;fs.writeFileSync(f.log+'.operator-state',JSON.stringify(op));}else if(kind==='original-proof'){const op=JSON.parse(fs.readFileSync(f.log+'.operator-state'));op.manifest=null;fs.writeFileSync(f.log+'.operator-state',JSON.stringify(op));}else{f.engine('control',true);f.engine('network',JSON.parse(fs.readFileSync(ip)).node_network);f.engine('replacement',true);}const before=fs.readFileSync(f.log,'utf8');check(f.invoke('destroy').status!==0,kind+' completion retry accepted');const after=fs.readFileSync(f.log,'utf8').slice(before.length);check(!after.includes('container start')&&!after.includes('compose --')&&!after.includes('network rm'),'failed original proof/replaced inventory mutated resources');}});
test('FailedResourceCleanupKeepsDBRegistry',()=>{const f=fixture();f.prepare();fs.writeFileSync(f.log+'.cleanup-fail','');const r=f.dev('destroy');check(r.status!==0,'failed cleanup succeeded');check(!fs.readFileSync(f.log,'utf8').includes('UNAPPROVED'),'DB cleanup attempted');check(fs.existsSync(path.join(f.state,'manifest.env')),'registry removed');fs.unlinkSync(f.log+'.cleanup-fail');const before=fs.readFileSync(f.log,'utf8');f.dev('destroy');check(JSON.parse(fs.readFileSync(path.join(f.state,'fleet','identity.json'))).cleanup_operation_key===JSON.parse(fs.readFileSync(path.join(f.state,'fleet','identity.json'))).operation_key,'finalized Delete native cleanup retry denied');check(f.invoke('destroy').status===0,'original Delete helper replay denied');const after=fs.readFileSync(f.log,'utf8').slice(before.length);check(after.includes('operator destroy')&&!after.includes('operator quiesce')&&!after.includes('container start')&&!after.includes('start api'),'retry used Stop/restart instead of original Delete');});
